CREATE TABLE inventory_matching_bucket_pages (
 tenant TEXT NOT NULL, page_id TEXT NOT NULL, generation_id TEXT NOT NULL, scope_id TEXT NOT NULL, key_class TEXT NOT NULL, bucket_hash TEXT NOT NULL,
 config_version INTEGER NOT NULL, work_version INTEGER NOT NULL, completed_version INTEGER NOT NULL,
 previous_version INTEGER NOT NULL, previous_set TEXT NOT NULL, next_version INTEGER NOT NULL, next_set TEXT NOT NULL,
 set_count INTEGER NOT NULL CHECK(set_count BETWEEN 0 AND 10), row_count INTEGER NOT NULL CHECK(row_count BETWEEN 0 AND 200), complete INTEGER NOT NULL CHECK(complete IN(0,1)),
 lease_token TEXT NOT NULL, lease_fence INTEGER NOT NULL, input_digest TEXT NOT NULL, prepared_at INTEGER NOT NULL,
 state TEXT NOT NULL DEFAULT 'prepared' CHECK(state IN('prepared','committed')), PRIMARY KEY(tenant,page_id),
 FOREIGN KEY(tenant,generation_id,scope_id,key_class,bucket_hash) REFERENCES inventory_matching_bucket_jobs(tenant,generation_id,scope_id,key_class,bucket_hash),
 CHECK((set_count=0 AND complete=1 AND (next_version,next_set)=(previous_version,previous_set)) OR (set_count>0 AND (next_version,next_set)>(previous_version,previous_set)))
);
CREATE TABLE inventory_matching_bucket_rows (
 tenant TEXT NOT NULL, page_id TEXT NOT NULL, destination TEXT NOT NULL, source_scope TEXT NOT NULL, record_key TEXT NOT NULL,
 source_config_version INTEGER NOT NULL, destination_config_version INTEGER NOT NULL, expected_work_version INTEGER NOT NULL, expected_completed_version INTEGER NOT NULL,
 PRIMARY KEY(tenant,page_id,destination,source_scope,record_key), FOREIGN KEY(tenant,page_id) REFERENCES inventory_matching_bucket_pages(tenant,page_id),
 FOREIGN KEY(tenant,destination) REFERENCES inventory_scopes(tenant,scope_id), FOREIGN KEY(tenant,source_scope) REFERENCES inventory_scopes(tenant,scope_id)
);
CREATE TABLE inventory_matching_bucket_guards (
 tenant TEXT NOT NULL, page_id TEXT NOT NULL, PRIMARY KEY(tenant,page_id), FOREIGN KEY(tenant,page_id) REFERENCES inventory_matching_bucket_pages(tenant,page_id)
);
CREATE VIEW inventory_matching_bucket_page_dependents AS
 SELECT p.tenant,p.page_id,p.generation_id,d.set_id,d.seen_version FROM inventory_matching_bucket_pages p CROSS JOIN inventory_matching_bucket_dependents d INDEXED BY inventory_matching_bucket_dependents_cursor
 WHERE d.tenant=p.tenant AND d.generation_id=p.generation_id AND d.scope_id=p.scope_id AND d.key_class=p.key_class AND d.bucket_hash=p.bucket_hash AND d.seen_version<p.work_version AND (d.seen_version,d.set_id)>(p.previous_version,p.previous_set) AND (d.seen_version,d.set_id)<=(p.next_version,p.next_set);
CREATE VIEW inventory_matching_bucket_page_candidates AS
 SELECT d.tenant,d.page_id,d.generation_id,r.destination,r.source_scope,r.record_key,rt.source_config_version,rt.destination_config_version
 FROM inventory_matching_bucket_page_dependents d CROSS JOIN match_results r INDEXED BY match_result_set
 JOIN inventory_matching_source_routes rt ON rt.tenant=r.tenant AND rt.generation_id=d.generation_id AND rt.destination=r.destination AND rt.source_scope=r.source_scope
 WHERE r.tenant=d.tenant AND r.set_id=d.set_id;
CREATE VIEW inventory_matching_bucket_stale_authority AS
 SELECT p.tenant,p.page_id FROM inventory_matching_bucket_pages p WHERE NOT EXISTS(
 SELECT 1 FROM inventory_matching_bucket_jobs j JOIN comparison_domains d ON d.tenant=j.tenant AND d.active_generation=j.generation_id
 JOIN inventory_comparison_ready_builds s ON s.tenant=j.tenant AND s.generation_id=j.generation_id AND s.scope_id=j.scope_id AND s.config_version=j.config_version
 JOIN leases l ON l.tenant=j.tenant AND l.scope=json_array('matching-bucket',j.generation_id,j.scope_id,j.key_class,j.bucket_hash) AND l.token=p.lease_token AND l.fence=p.lease_fence AND l.expires_at>unixepoch('subsec')*1000
 WHERE j.tenant=p.tenant AND j.generation_id=p.generation_id AND j.scope_id=p.scope_id AND j.key_class=p.key_class AND j.bucket_hash=p.bucket_hash AND j.config_version=p.config_version AND j.work_version=p.work_version AND p.prepared_at>0 AND p.prepared_at<=unixepoch('subsec')*1000);
CREATE VIEW inventory_matching_bucket_invalid_rows AS
 SELECT q.tenant,q.page_id FROM inventory_matching_bucket_rows q JOIN inventory_matching_bucket_pages h ON h.tenant=q.tenant AND h.page_id=q.page_id WHERE NOT EXISTS(
 SELECT 1 FROM match_results r JOIN inventory_matching_bucket_page_dependents dep ON dep.tenant=r.tenant AND dep.page_id=q.page_id AND dep.set_id=r.set_id
 JOIN inventory_matching_source_routes rt ON rt.tenant=r.tenant AND rt.generation_id=h.generation_id AND rt.destination=r.destination AND rt.source_scope=r.source_scope AND rt.source_config_version=q.source_config_version AND rt.destination_config_version=q.destination_config_version
 WHERE r.tenant=q.tenant AND r.destination=q.destination AND r.source_scope=q.source_scope AND r.record_key=q.record_key);
CREATE TRIGGER inventory_matching_bucket_page_admit AFTER INSERT ON inventory_matching_bucket_pages BEGIN
 SELECT CASE WHEN NEW.state!='prepared' OR EXISTS(SELECT 1 FROM inventory_matching_bucket_stale_authority WHERE tenant=NEW.tenant AND page_id=NEW.page_id) OR NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_jobs j WHERE j.tenant=NEW.tenant AND j.generation_id=NEW.generation_id AND j.scope_id=NEW.scope_id AND j.key_class=NEW.key_class AND j.bucket_hash=NEW.bucket_hash AND j.work_version=NEW.work_version AND j.completed_version=NEW.completed_version AND j.completed_version<j.work_version AND j.cursor_version=NEW.previous_version AND j.cursor_set=NEW.previous_set) THEN RAISE(ABORT,'inventory matching bucket authority changed') END;
 SELECT CASE WHEN NEW.set_count!=(SELECT count(*) FROM inventory_matching_bucket_page_dependents WHERE tenant=NEW.tenant AND page_id=NEW.page_id) OR NEW.row_count!=(SELECT count(*) FROM inventory_matching_bucket_page_candidates WHERE tenant=NEW.tenant AND page_id=NEW.page_id) OR (NEW.complete=1 AND EXISTS(SELECT 1 FROM inventory_matching_bucket_dependents d INDEXED BY inventory_matching_bucket_dependents_cursor WHERE d.tenant=NEW.tenant AND d.generation_id=NEW.generation_id AND d.scope_id=NEW.scope_id AND d.key_class=NEW.key_class AND d.bucket_hash=NEW.bucket_hash AND d.seen_version<NEW.work_version AND (d.seen_version,d.set_id)>(NEW.next_version,NEW.next_set))) THEN RAISE(ABORT,'inventory matching bucket range incomplete') END;
END;
CREATE TRIGGER inventory_matching_bucket_guard BEFORE INSERT ON inventory_matching_bucket_guards BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_pages h WHERE h.tenant=NEW.tenant AND h.page_id=NEW.page_id AND h.state='prepared' AND h.row_count=(SELECT count(*) FROM inventory_matching_bucket_rows WHERE tenant=h.tenant AND page_id=h.page_id)) OR EXISTS(SELECT 1 FROM inventory_matching_bucket_stale_authority WHERE tenant=NEW.tenant AND page_id=NEW.page_id) OR EXISTS(SELECT 1 FROM inventory_matching_bucket_invalid_rows WHERE tenant=NEW.tenant AND page_id=NEW.page_id) THEN RAISE(ABORT,'inventory matching bucket manifest incomplete') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_matching_bucket_rows q JOIN inventory_matching_bucket_pages h ON h.tenant=q.tenant AND h.page_id=q.page_id LEFT JOIN matching_work w ON w.tenant=q.tenant AND w.generation_id=h.generation_id AND w.destination=q.destination AND w.source_scope=q.source_scope AND w.record_key=q.record_key WHERE q.tenant=NEW.tenant AND q.page_id=NEW.page_id AND (q.expected_work_version!=coalesce(w.work_version,0) OR q.expected_completed_version!=coalesce(w.completed_version,0))) THEN RAISE(ABORT,'inventory matching bucket work changed') END;
END;
CREATE TRIGGER inventory_matching_bucket_job_progress BEFORE UPDATE ON inventory_matching_bucket_jobs WHEN NEW.work_version=OLD.work_version AND (NEW.completed_version!=OLD.completed_version OR NEW.cursor_version!=OLD.cursor_version OR NEW.cursor_set!=OLD.cursor_set) BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_pages p JOIN inventory_matching_bucket_guards g ON g.tenant=p.tenant AND g.page_id=p.page_id WHERE p.tenant=OLD.tenant AND p.generation_id=OLD.generation_id AND p.scope_id=OLD.scope_id AND p.key_class=OLD.key_class AND p.bucket_hash=OLD.bucket_hash AND p.state='prepared' AND p.work_version=OLD.work_version AND p.completed_version=OLD.completed_version AND p.previous_version=OLD.cursor_version AND p.previous_set=OLD.cursor_set AND p.next_version=NEW.cursor_version AND p.next_set=NEW.cursor_set AND NEW.completed_version=CASE p.complete WHEN 1 THEN p.work_version ELSE p.completed_version END AND NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_stale_authority x WHERE x.tenant=p.tenant AND x.page_id=p.page_id)) THEN RAISE(ABORT,'inventory matching bucket progress guard missing') END;
END;
CREATE TRIGGER inventory_matching_bucket_page_commit BEFORE UPDATE ON inventory_matching_bucket_pages BEGIN
 SELECT CASE WHEN OLD.state!='prepared' OR NEW.state!='committed' OR NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_guards WHERE tenant=OLD.tenant AND page_id=OLD.page_id) OR EXISTS(SELECT 1 FROM inventory_matching_bucket_stale_authority WHERE tenant=OLD.tenant AND page_id=OLD.page_id) OR NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_jobs j WHERE j.tenant=OLD.tenant AND j.generation_id=OLD.generation_id AND j.scope_id=OLD.scope_id AND j.key_class=OLD.key_class AND j.bucket_hash=OLD.bucket_hash AND j.work_version=OLD.work_version AND j.completed_version=CASE OLD.complete WHEN 1 THEN OLD.work_version ELSE OLD.completed_version END AND j.cursor_version=OLD.next_version AND j.cursor_set=OLD.next_set) THEN RAISE(ABORT,'inventory matching bucket commit changed') END;
 SELECT CASE WHEN OLD.set_count!=(SELECT count(*) FROM inventory_matching_bucket_page_dependents WHERE tenant=OLD.tenant AND page_id=OLD.page_id) OR OLD.row_count!=(SELECT count(*) FROM inventory_matching_bucket_page_candidates WHERE tenant=OLD.tenant AND page_id=OLD.page_id) OR EXISTS(SELECT 1 FROM inventory_matching_bucket_invalid_rows WHERE tenant=OLD.tenant AND page_id=OLD.page_id) THEN RAISE(ABORT,'inventory matching bucket census changed') END;
 SELECT CASE WHEN (SELECT count(*) FROM inventory_matching_bucket_rows q CROSS JOIN matching_work w WHERE q.tenant=OLD.tenant AND q.page_id=OLD.page_id AND w.tenant=q.tenant AND w.generation_id=OLD.generation_id AND w.destination=q.destination AND w.source_scope=q.source_scope AND w.record_key=q.record_key AND w.work_version=q.expected_work_version+1 AND w.completed_version=q.expected_completed_version AND w.source_config_version=q.source_config_version AND w.destination_config_version=q.destination_config_version)!=OLD.row_count THEN RAISE(ABORT,'inventory matching bucket publication incomplete') END;
END;
CREATE TRIGGER inventory_matching_bucket_page_identity BEFORE UPDATE ON inventory_matching_bucket_pages WHEN (NEW.tenant,NEW.page_id,NEW.generation_id,NEW.scope_id,NEW.key_class,NEW.bucket_hash,NEW.config_version,NEW.work_version,NEW.completed_version,NEW.previous_version,NEW.previous_set,NEW.next_version,NEW.next_set,NEW.set_count,NEW.row_count,NEW.complete,NEW.lease_token,NEW.lease_fence,NEW.input_digest,NEW.prepared_at) IS NOT (OLD.tenant,OLD.page_id,OLD.generation_id,OLD.scope_id,OLD.key_class,OLD.bucket_hash,OLD.config_version,OLD.work_version,OLD.completed_version,OLD.previous_version,OLD.previous_set,OLD.next_version,OLD.next_set,OLD.set_count,OLD.row_count,OLD.complete,OLD.lease_token,OLD.lease_fence,OLD.input_digest,OLD.prepared_at) BEGIN SELECT RAISE(ABORT,'immutable inventory matching bucket receipt'); END;
CREATE TRIGGER inventory_matching_bucket_row_insert BEFORE INSERT ON inventory_matching_bucket_rows WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_pages h WHERE h.tenant=NEW.tenant AND h.page_id=NEW.page_id AND h.state='prepared' AND NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_guards g WHERE g.tenant=h.tenant AND g.page_id=h.page_id)) BEGIN SELECT RAISE(ABORT,'inventory matching bucket rows closed'); END;
CREATE TRIGGER inventory_matching_bucket_row_update BEFORE UPDATE ON inventory_matching_bucket_rows BEGIN SELECT RAISE(ABORT,'immutable inventory matching bucket row'); END;
CREATE TRIGGER inventory_matching_bucket_page_delete BEFORE DELETE ON inventory_matching_bucket_pages WHEN OLD.state!='committed' OR OLD.prepared_at>unixepoch('subsec')*1000-604800000 BEGIN SELECT RAISE(ABORT,'retained inventory matching bucket receipt'); END;
CREATE TRIGGER inventory_matching_bucket_row_delete BEFORE DELETE ON inventory_matching_bucket_rows WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_bucket_pages h WHERE h.tenant=OLD.tenant AND h.page_id=OLD.page_id AND h.state='committed' AND h.prepared_at<unixepoch('subsec')*1000-604800000) BEGIN SELECT RAISE(ABORT,'retained inventory matching bucket row'); END;
